import type { Source, SourceArgs } from "./Core";
/**
 * A callbag sink that listens to a callbag source
 * and invokes the callbacks passed in. It does not
 * pull values from the source. Instead, it performs
 * actions transparently.
 *
 * @param listener A object with callbacks or a single
 *     data callback that listens to the stream.
 *
 * @internal
 */
export declare const tap: <T, E>(listener?: {
    next?: ((data: T) => void) | undefined;
    error?: ((err: E) => void) | undefined;
    complete?: (() => void) | undefined;
} | ((data: T) => void)) => (source: Source<T, E>) => (...sourceArgs: SourceArgs<T, E>) => void;
